mapper.select:
SELECT ord.* , cp.id as 'project.id', cp.name as 'project.name', cp.short_name as 'project.shortName', cp.serial_number as 'project.serialNumber' FROM scm_subcontract_order AS ord LEFT JOIN contract_project as cp on ord.project_id = cp.id AND cp.bool_delete_enum = 0
ord.bool_delete_enum = 0
AND cp.name like concat('%',#{projectName},'%')
AND date_format(ord.sign_date,'%Y') = #{year}
AND DATE(ord.sign_date) >= DATE(#{startDate})
AND DATE(ord.sign_date) <= DATE(#{endDate})
AND ord.serial_number like concat('%',#{serialNumber},'%')
AND ord.project_id = #{projectId}
AND ord.supplier_name like concat('%',#{supplierName},'%')
AND ord.subcontract_class_id = #{subcontractClassId}
AND ord.bool_settlement_status = #{boolSettlementStatus}
AND ord.user_name like concat('%',#{userName},'%')
order by ord.sign_date desc

SELECT a.* FROM scm_subcontract_order a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN sys_branch_company bc ON bc.id = a.branch_company_id LEFT JOIN scm_supplier ss ON ss.id = a.supplier_id LEFT JOIN sys_user su ON su.id = a.user_id LEFT JOIN sys_user su2 ON su2.id = a.project_manager_id
a.bool_delete_enum = 0
AND date_format(a.create_time,'%Y') = date_format(#{year},'%Y')
AND a.project_manager_id = #{projectManagerId}
AND a.project_attribute in
#{attribute}
AND a.audit_type_enum = #{auditTypeEnum}
AND a.bool_settlement_status = #{boolSettlementStatus}
and su.name like CONCAT('%', #{userName},'%')
AND su2.name like CONCAT('%', #{projectManagerName},'%')
and a.branch_company_id = #{branchCompanyId}
and (bc.name like CONCAT('%', #{branchCompanyName},'%') or bc.short_name like CONCAT('%', #{branchCompanyName},'%'))
and a.supplier_id = #{supplierId}
and ss.name like CONCAT('%', #{supplierName},'%')
and a.serial_number like CONCAT('%', #{serialNumber},'%')
and a.project_id = #{projectId}
and (cp.name like CONCAT('%', #{projectName},'%') or cp.short_name like CONCAT('%', #{projectName},'%'))
and a.level = #{level}
GROUP BY a.id ORDER BY a.bool_settlement_status ASC, a.id DESC
